// Bakes a curated set of Bootstrap Icons (MIT) into src/lib/gallery/icons.ts as
// cut-ready GalleryShape paths. Run once: `node scripts/gen-icons.mjs`.
// Needs `bootstrap-icons` installed at the repo root and svgpath + svg-path-bounds
// in scripts/. The generated file is self-contained; the deps can be removed after.
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";

const require = createRequire(path.join(process.cwd(), "scripts/package.json"));
const svgpath = require("svgpath");
const getBounds = require("svg-path-bounds");

const ICON_DIR = path.join(process.cwd(), "node_modules/bootstrap-icons/icons");
const OUT = path.join(process.cwd(), "src/lib/gallery/icons.ts");
const SIZE_MM = 56;

const NAMES = `
heart-fill heartbreak-fill hearts suit-heart-fill suit-spade-fill suit-club-fill suit-diamond-fill
star-fill stars star-half flower1 flower2 flower3 tree-fill sun-fill moon-fill moon-stars-fill
cloud-fill clouds-fill cloud-sun-fill cloud-rain-fill cloud-moon-fill lightning-fill lightning-charge-fill
droplet-fill droplet-half snow snow2 snow3 umbrella-fill balloon-fill balloon-heart-fill gift-fill
cup-fill cup-hot-fill cup-straw egg-fried emoji-smile-fill emoji-heart-eyes-fill emoji-laughing-fill
emoji-sunglasses-fill emoji-kiss-fill hand-thumbs-up-fill heart-pulse-fill lightbulb-fill
music-note music-note-beamed music-note-list camera-fill camera-reels-fill airplane-fill car-front-fill
bicycle bus-front-fill truck rocket-fill rocket-takeoff-fill house-fill house-heart-fill house-door-fill
cart-fill bag-fill bag-heart-fill basket-fill tag-fill tags-fill bookmark-fill bookmark-star-fill
bookmark-heart-fill trophy-fill award-fill key-fill bell-fill chat-fill chat-heart-fill chat-dots-fill
envelope-fill envelope-heart-fill telephone-fill clock-fill alarm-fill calendar-fill calendar-heart-fill
geo-alt-fill flag-fill shield-fill shield-check gem palette-fill brush-fill scissors pencil-fill pen-fill
magic fire eyedropper rulers pin-angle-fill paperclip trash-fill folder-fill image-fill images film
play-fill pause-fill stop-fill record-circle-fill mic-fill headphones speaker-fill controller
dice-5-fill puzzle-fill globe globe-americas cpu-fill bank book-fill journal-bookmark-fill mortarboard-fill
eyeglasses smartwatch phone-fill laptop-fill gear-fill tools hammer wrench nut-fill paint-bucket
person-fill person-heart people-fill patch-check-fill compass-fill map-fill signpost-fill cone-striped
fuel-pump-fill brightness-high-fill thermometer-sun thermometer-snow wind tornado crosshair bullseye
`.split(/\s+/).filter(Boolean);

const title = (n) =>
  n.replace(/-fill$|-fill-|[0-9]+$/g, " ").replace(/-/g, " ").trim().replace(/\b\w/g, (c) => c.toUpperCase()) || n;

const shapes = [];
const seenLabels = new Set();
for (const name of NAMES) {
  const file = path.join(ICON_DIR, name + ".svg");
  if (!fs.existsSync(file)) continue;
  const svg = fs.readFileSync(file, "utf8");
  const ds = [...svg.matchAll(/<path[^>]*\bd="([^"]+)"/g)].map((m) => m[1]);
  if (ds.length === 0) continue;
  const combined = ds.join(" ");
  let bounds;
  try {
    bounds = getBounds(combined);
  } catch {
    continue;
  }
  const [minX, minY, maxX, maxY] = bounds;
  const w = maxX - minX;
  const h = maxY - minY;
  if (!(w > 0) || !(h > 0) || !Number.isFinite(w) || !Number.isFinite(h)) continue;
  const s = SIZE_MM / Math.max(w, h);
  // unarc: A→C, unshort: S/T→C/Q, abs: absolute — leaving only M/L/C/Q/Z that
  // the app's path parser fully supports.
  const d = svgpath(combined).unarc().unshort().scale(s).translate(-minX * s, -minY * s).abs().round(2).toString();
  const label = title(name);
  const uniqueLabel = seenLabels.has(label) ? `${label} ${name.replace(/[^0-9]/g, "") || ""}`.trim() : label;
  seenLabels.add(label);
  shapes.push({
    id: "bi-" + name,
    name: uniqueLabel,
    category: "Icons",
    d,
    width: Number((w * s).toFixed(2)),
    height: Number((h * s).toFixed(2)),
  });
}

const header = `/**
 * Open icon pack — a curated set of Bootstrap Icons (https://icons.getbootstrap.com),
 * MIT licensed (Copyright (c) 2019-2024 The Bootstrap Authors), baked into
 * cut-ready GalleryShape paths. Generated by scripts/gen-icons.mjs — do not edit by hand.
 */
import type { GalleryShape } from "./catalog";

export const ICONS: GalleryShape[] = ${JSON.stringify(shapes, null, 2)};
`;

fs.writeFileSync(OUT, header);
console.log(`Wrote ${shapes.length} icons to ${path.relative(process.cwd(), OUT)}`);
